SELECT P.ID, P.TITULO, P.CANAL_ID, C.NOME CANAL, P.QTD_YT, COUNT(V.ID) QTD, SUM(V.STATUS = 'ESTUDADO') ESTUDADOS FROM PLAYLISTS P JOIN CANAIS C ON C.ID = P.CANAL_ID JOIN PLAYLIST_VIDEOS PV ON PV.PLAYLIST_ID = P.ID JOIN VIDEOS V ON V.YT_VIDEO_ID = PV.YT_VIDEO_ID WHERE V.STATUS <> 'FORA' AND (V.STATUS <> 'FORA_TEMA' OR '{{status}}' = 'FORA_TEMA') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{status}}' = '' OR V.STATUS = '{{status}}') AND ({{nTemas}} = 0 OR V.ID IN (SELECT XT.VIDEO_ID FROM VIDEO_TEMAS XT WHERE FIND_IN_SET(XT.TEMA_ID, '{{temas}}') GROUP BY XT.VIDEO_ID HAVING COUNT(DISTINCT XT.TEMA_ID) = {{nTemas}})) AND ({{nPlay}} = 0 OR V.YT_VIDEO_ID IN (SELECT XP.YT_VIDEO_ID FROM PLAYLIST_VIDEOS XP WHERE FIND_IN_SET(XP.PLAYLIST_ID, '{{playlists}}') GROUP BY XP.YT_VIDEO_ID HAVING COUNT(DISTINCT XP.PLAYLIST_ID) = {{nPlay}})) AND ({{nPrat}} = 0 OR V.ID IN (SELECT XR.VIDEO_ID FROM PRATICAS XR WHERE XR.CONSELHO = 0 AND FIND_IN_SET(XR.JEITO, '{{praticas}}') GROUP BY XR.VIDEO_ID HAVING COUNT(DISTINCT XR.JEITO) = {{nPrat}})) AND ('{{origem}}' = '' OR V.ORIGEM = '{{origem}}') GROUP BY P.ID, P.TITULO, P.CANAL_ID, C.NOME, P.QTD_YT, P.ORDEM ORDER BY P.CANAL_ID, P.ORDEM